<template>
  <F7App v-bind="f7Params">
    <F7View name="home" id="view-home" main url="/"></F7View>

    <UpdatePrompt />
  </F7App>
</template>

<script setup lang="ts">
import type Framework7 from "framework7";
import UpdatePrompt from "./shared/components/updater/UpdatePrompt.vue";

const device = getDevice();
const f7Params = framework7();

onMounted(async () => {
  const authStore = useAuthStore();
  const serverStore = useServerStore();

  await Promise.all([authStore.init(), serverStore.init()]);

  f7ready(async (f7: Framework7) => {
    useAuthGuard();

    if (device.capacitor) {
      await capacitorPlugin.init(f7);
    }
  });
});
</script>
